// Metres in the rendered blade's local coordinates. Shared by mesh and collider.
export const BAT_STATIONS=[[-.28,.083,.019],[-.265,.101,.023],[-.19,.108,.052],[-.07,.108,.061],[.10,.106,.045],[.23,.102,.029],[.285,.076,.020],[.335,.026,.017]];
export function bladeMesh(){const positions=[],uv=[],indices=[];BAT_STATIONS.forEach(([y,w,d],row)=>{const ring=[[-w/2,.011],[0,.015+Math.sin((y+.28)*4)*.003],[w/2,.011],[w/2,-.012],[0,-d],[-w/2,-.012]];for(const [x,z] of ring){positions.push(x,y,z);uv.push(x/.108+.5,(y+.28)/.615);}if(row)for(let k=0;k<6;k++){const a=(row-1)*6+k,b=(row-1)*6+(k+1)%6,c=row*6+k,e=row*6+(k+1)%6;indices.push(a,b,c,b,e,c);}});for(let k=1;k<5;k++){indices.push(0,k,k+1);const b=(BAT_STATIONS.length-1)*6;indices.push(b,b+k+1,b+k);}for(let i=2;i<positions.length;i+=3)positions[i]*=-1;for(let i=0;i<indices.length;i+=3)[indices[i+1],indices[i+2]]=[indices[i+2],indices[i+1]];return {positions,uv,indices};}
export function contactRegion(p,normal){if(p.y>.335)return 'handle';if(p.y>.24)return 'shoulder';if(p.y<-.255)return 'toe';if(Math.abs(normal.x)>.55)return p.x<0?'left edge':'right edge';if(p.y<-.17)return 'lower blade';if(p.y>.10)return 'upper blade';return 'sweet spot';}
export const REGION_RESTITUTION={'sweet spot':1,'lower blade':.78,'upper blade':.75,'left edge':.55,'right edge':.55,toe:.45,shoulder:.48,handle:.25};
